# Validate before Load so an invalid body is a 400, not masked by a 404.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheetId}/claims/{claimId}/status: action is open, settle, approve, reject
 *  or void; reason is required to reject, and to void
 *  (one on the sheet's list) while the sheet has void reasons. */
public record ClaimStatusRequest(String action, String user, String reason) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.hq.app.voidreason.VoidReasons;

public class ValidateClaimStatus {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimStatusRequest request, Out<ValidClaimStatus> body, Settings settings,
            VoidReasons voidReasons)
            throws InvalidClaimException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String action = request.action() == null ? "" : request.action().trim();
        String reason = request.reason() == null ? "" : request.reason().trim();
        ValidClaimStatus valid = switch (action) {
            case "open" -> new ValidClaimStatus(ClaimStatus.OPEN, request.user(), ValidClaimStatus.Decision.NONE, null);
            case "settle" -> new ValidClaimStatus(ClaimStatus.SETTLED, request.user(), ValidClaimStatus.Decision.NONE, null);
            case "void" -> {
                // While the sheet has void reasons, a void needs one chosen from them; without any, none is kept.
                if (voidReasons.list(sheetId).isEmpty()) {
                    yield new ValidClaimStatus(ClaimStatus.VOID, request.user(), ValidClaimStatus.Decision.NONE, null);
                }
                if (reason.isEmpty() || !voidReasons.contains(sheetId, reason)) {
                    throw new InvalidClaimException("A void needs a reason from the sheet's list");
                }
                yield new ValidClaimStatus(ClaimStatus.VOID, request.user(), ValidClaimStatus.Decision.NONE, reason);
            }
            case "approve" -> new ValidClaimStatus(ClaimStatus.SETTLED, request.user(), ValidClaimStatus.Decision.APPROVE, null);
            case "reject" -> {
                if (reason.isEmpty()) throw new InvalidClaimException("A rejection needs a reason");
                yield new ValidClaimStatus(ClaimStatus.OPEN, request.user(), ValidClaimStatus.Decision.REJECT, reason);
            }
            default -> throw new InvalidClaimException("No such status change: " + action);
        };
        body.set(valid);
    }
}
package net.officefloor.hq.app.claim;

/** A status change that names a known action: its target status, whether it is a steward's decision
 *  on a PENDING claim (approve or reject), and the reason given to reject (or chosen from the sheet's list to void; null for none). */
public record ValidClaimStatus(ClaimStatus target, String user, Decision decision, String reason) {

    /** A steward's decision on a PENDING claim; NONE for any other status change. */
    public enum Decision { NONE, APPROVE, REJECT }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyClaimStatus {
    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, ClaimLog log, Out<ClaimNumber> number)
            throws ClaimStatusRefusedException {
        number.set(change(request, claim, sheets, people, rates, periods, settings, numbering, log));
    }

    /** Applies a status change to the claim by the rules of a single change, returning its number;
     *  throws, leaving the claim as it is, when the change is refused. Bulk settle uses it too. */
    static ClaimNumber change(ValidClaimStatus request, Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, ClaimLog log)
            throws ClaimStatusRefusedException {
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
            throw new ClaimStatusRefusedException("No claim whose due-by is inside a closed period can change status");
        }
        boolean steward = Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()));
        if (request.decision() == ValidClaimStatus.Decision.NONE) {
            // Opening, settling and voiding are each taken only by the roles the sheet's permission allows.
            String action = switch (request.target()) {
                case OPEN -> "open";
                case SETTLED -> "settle";
                default -> "void";
            };
            if (!settings.allows(claim.getSheetId(), request.user(), action)) {
                throw new ClaimStatusRefusedException("Your role may not " + action + " a claim on this sheet");
            }
        }
        if (request.decision() != ValidClaimStatus.Decision.NONE) {
            // Only a steward approves or rejects, and only a PENDING claim.
            if (claim.getStatus() != ClaimStatus.PENDING) {
                throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
            }
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can approve or reject a PENDING claim");
            }
        } else if (!claim.getStatus().canBecome(request.target())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
        }
        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(request.user())) {
            // Four eyes: the user who opened a claim cannot settle (or approve) it.
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (request.target() == ClaimStatus.SETTLED && claim.getEditedBy() != null
                && claim.getEditedBy().equals(request.user())) {
            // Four eyes: nor can the user who last edited it.
            throw new ClaimStatusRefusedException("The user who last edited a claim cannot settle it");
        }
        if (request.target() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until its deferred-until date");
        }
        if (request.target() == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
            // Only a steward voids a SETTLED claim, and only within 7 days of its settlement by the sheet's today.
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can void a SETTLED claim");
            }
            LocalDate settledOn = log.settledOn(claim);
            if (settledOn == null || sheets.today(claim.getSheetId()).isAfter(settledOn.plusDays(7))) {
                throw new ClaimStatusRefusedException("A SETTLED claim can be voided only within 7 days of its settlement");
            }
        }
        ClaimStatus target = request.target();
        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
            refuseNoteless(claim, sheets, people, rates, settings, rounding);
        }
        if (target == ClaimStatus.SETTLED && claim.getProofs() == 0) {
            // Above the proof threshold in force on the claim's date a claim needs a proof to be settled or approved,
            // judged on its due as shown (before the clerk limit is considered); a due of n/a is within any threshold.
            // The person's grade's own threshold in force then, when one is set, takes the place of the sheet's.
            BigDecimal threshold = settings.proofThresholdFor(claim.getSheetId(),
                    people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate()), claim.getDate());
            BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
            if (threshold != null && due != null && due.compareTo(threshold) > 0) {
                throw new ClaimStatusRefusedException("A claim whose due is above the proof threshold needs a proof to be settled");
            }
        }
        if (target == ClaimStatus.SETTLED && request.decision() == ValidClaimStatus.Decision.NONE && !steward) {
            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
            // a due of n/a is within any limit.
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                // Above the clerk limit the claim awaits a steward's approval.
                target = ClaimStatus.PENDING;
            }
        }
        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
            claim.setNumber(numbering.next(claim.getSheetId(), claim.getPeriodDate()));
            claim.setOpenedBy(request.user());
        }
        // A voided claim keeps its number; numbers are never reused.
        ClaimNumber number = new ClaimNumber(claim.getNumber());
        if (target == ClaimStatus.SETTLED) {
            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount
            // at the rate in force on the claim's date, with its late charge as of today on top and raised to the floor, frozen in;
            // with no figure it stays live (n/a until a rate is set).
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()), rounding);
            claim.setSettledDue(LateCharge.due(claim, figure, settings.floor(claim.getSheetId(), claim.getDate()),
                    on -> settings.latePct(claim.getSheetId(), on), sheets.today(claim.getSheetId()), rounding,
                    settings.grace(claim.getSheetId(), grade, claim.getDate())));
        }
        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
        if (target == ClaimStatus.VOID) {
            claim.setVoidReason(request.reason());
        }
        claim.setStatus(target);
        return number;
    }

    /** Refuses opening a claim with an empty note whose due as shown is above the note threshold in force on its date;
     *  a due of n/a is within any threshold. Bulk open uses it too. */
    static void refuseNoteless(Claim claim, Sheets sheets, People people, Rates rates, Settings settings,
            RoundingMode rounding) throws ClaimStatusRefusedException {
        if (claim.getNote() != null && !claim.getNote().trim().isEmpty()) {
            return;
        }
        BigDecimal threshold = settings.noteThreshold(claim.getSheetId(), claim.getDate());
        if (threshold == null) {
            return;
        }
        BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
        if (due != null && due.compareTo(threshold) > 0) {
            throw new ClaimStatusRefusedException("A claim whose due is above the note threshold needs a note to be opened");
        }
    }

    /** The claim's due as shown: fixed (settled or bound), else its live figure with its late charge as of today; null for n/a. */
    private static BigDecimal shownDue(Claim claim, Sheets sheets, People people, Rates rates, Settings settings,
            RoundingMode rounding) {
        String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal fixed = ClaimResponse.fixedDue(claim);
        BigDecimal figure = fixed != null || claim.isBound() ? fixed
                : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()), rounding);
        return LateCharge.due(claim, figure, settings.floor(claim.getSheetId(), claim.getDate()),
                on -> settings.latePct(claim.getSheetId(), on), sheets.today(claim.getSheetId()), rounding,
                settings.grace(claim.getSheetId(), grade, claim.getDate()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.plugin.variable.Val;

public class AuditClaimStatus {
    public void audit(@Val ValidClaimStatus request, @Val Claim claim, @Val ClaimNumber number, People people, Audit audit, @Val RollupFigures before, Rollup rollup, ClaimLog log, Watches watches) {
        record(request, claim, number, people, audit, before, rollup, log, watches);
    }

    /** Logs and audits a status change that went through, as a single change does. Bulk settle uses it too. */
    static void record(ValidClaimStatus request, Claim claim, ClaimNumber number, People people, Audit audit, RollupFigures before, Rollup rollup, ClaimLog log, Watches watches) {
        String event = switch (request.decision()) {
            case APPROVE -> "CLAIM_APPROVED";
            case REJECT -> "CLAIM_REJECTED";
            case NONE -> switch (claim.getStatus()) {
                case OPEN -> "CLAIM_OPENED";
                case PENDING -> "CLAIM_PENDING";
                case SETTLED -> "CLAIM_SETTLED";
                case VOID -> "CLAIM_VOIDED";
                case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
            };
        };
        net.officefloor.hq.app.person.Person person = people.find(claim.getSheetId(), claim.getPersonId());
        // Read before this change's own line is logged.
        boolean voidedSettled = claim.getStatus() == ClaimStatus.VOID
                && ClaimStatus.SETTLED.name().equals(log.lastStatus(claim));
        log.record(claim, person, request.user());
        String line = ClaimAudit.line(event, request.user(), person, claim, number.value());
        if (voidedSettled) {
            // A voided SETTLED claim reverses its frozen figure out of every total.
            line += " reversed=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        if (request.decision() == ValidClaimStatus.Decision.REJECT) {
            line += " reason=" + request.reason();
        }
        if (claim.getStatus() == ClaimStatus.VOID && request.reason() != null) {
            line += " reason=" + request.reason();
        }
        audit.recordOnCommit(line);
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            // Settled or approved: each user watching the person is notified, after the claim's own line.
            watches.notifyWatchers(person, request.user(), number.value(), audit);
        }
        rollup.recordChanges(claim.getSheetId(), request.user(), before);
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts DRAFT; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. A clerk
 * settling above the clerk limit sends an OPEN claim to PENDING instead: a steward approves it
 * (-> SETTLED) or rejects it (-> OPEN); a PENDING claim may also be voided, and a steward may void a SETTLED claim
 * within 7 days of its settlement.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to the target status. */
    public boolean canBecome(ClaimStatus target) {
        return switch (target) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED;
            case DRAFT -> false;
        };
    }

    /** Only OPEN, PENDING and SETTLED claims count toward claimed and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** OPEN and PENDING claims are open: their due is live, they go overdue and a hold covering their date takes them out of the totals (unless bound). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * A claim's status log: each status it takes is written as "<STATUS> by <user> on <date> due=<due>", the date
 * being the sheet's today and the due the claim's due as shown at that moment (n/a when it has none).
 */
@Service
public class ClaimLog {

    private final JdbcTemplate jdbc;
    private final Rollup rollup;
    private final Sheets sheets;

    public ClaimLog(JdbcTemplate jdbc, Rollup rollup, Sheets sheets) {
        this.jdbc = jdbc;
        this.rollup = rollup;
        this.sheets = sheets;
    }

    /** The date the claim was last settled (its latest SETTLED line), null if never. */
    public java.time.LocalDate settledOn(Claim claim) {
        List<Date> dates = jdbc.queryForList("SELECT log_date FROM claim_log WHERE sheet_id = ? AND claim_id = ? AND status = ?"
                + " ORDER BY id DESC", Date.class, claim.getSheetId(), claim.getId(), ClaimStatus.SETTLED.name());
        return dates.isEmpty() ? null : dates.get(0).toLocalDate();
    }

    /** The status of the claim's latest log line, null if it has none. */
    public String lastStatus(Claim claim) {
        List<String> statuses = jdbc.queryForList("SELECT status FROM claim_log WHERE sheet_id = ? AND claim_id = ?"
                + " ORDER BY id DESC", String.class, claim.getSheetId(), claim.getId());
        return statuses.isEmpty() ? null : statuses.get(0);
    }

    /** Log the claim's (new) status, as changed by the user. */
    public void record(Claim claim, Person person, String user) {
        BigDecimal due = rollup.due(claim, person);
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                claim.getSheetId(), claim.getId(), claim.getStatus().name(), user,
                Date.valueOf(sheets.today(claim.getSheetId())), due == null ? "n/a" : due.setScale(2).toPlainString());
    }
}

